<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Pesanan - CozyCafe</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= e(BASE_URL) ?>/assets/css/style.css"></head><body><?php require dirname(__DIR__) . '/layouts/admin_header.php'; ?><?php require dirname(__DIR__) . '/layouts/admin_sidebar.php'; ?>
<main class="admin-main container-fluid p-4"><h1 class="h3 mb-4">Kelola Pesanan</h1><?php if ($flash): ?><div class="alert alert-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<form class="mb-3" method="get"><select class="form-select w-auto" name="status" onchange="this.form.submit()"><option value="">Semua status</option><?php foreach (['Menunggu Konfirmasi','Dikonfirmasi','Sedang Disiapkan','Siap Disajikan','Selesai','Dibatalkan'] as $value): ?><option <?= ($_GET['status']??'')==$value?'selected':'' ?>><?= e($value) ?></option><?php endforeach; ?></select></form>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Subtotal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($orders as $order): ?><?php $isCanceled = $order['order_status']==='Dibatalkan' || $order['booking_status']==='Dibatalkan'; ?><tr><td><?= e($order['transaction_code']) ?></td><td><?= e($order['customer_name']) ?></td><td><?= format_rupiah($order['subtotal']) ?></td><td><?php if ($isCanceled): ?><span class="badge bg-secondary">Dibatalkan</span><?php elseif ($order['order_status']==='Selesai'): ?><span class="badge bg-success">Selesai</span><?php else: ?><form method="post" action="<?= e(BASE_URL) ?>/admin/orders/status"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= e($order['id']) ?>"><select class="form-select form-select-sm d-inline-block w-auto" name="order_status"><option selected><?= e($order['order_status']) ?></option><?php if ($order['order_status']==='Menunggu Konfirmasi'): ?><option>Dikonfirmasi</option><?php endif; ?><?php if ($order['order_status']==='Dikonfirmasi'): ?><option>Sedang Disiapkan</option><option>Siap Disajikan</option><option>Selesai</option><?php endif; ?><?php if ($order['order_status']==='Sedang Disiapkan'): ?><option>Siap Disajikan</option><option>Selesai</option><?php endif; ?><?php if ($order['order_status']==='Siap Disajikan'): ?><option>Selesai</option><?php endif; ?></select><button class="btn btn-sm btn-outline-coffee ms-1">Simpan</button></form><?php endif; ?></td><td><?php if (!$isCanceled && !in_array($order['order_status'],['Selesai'],true)): ?><a class="btn btn-sm btn-coffee" href="<?= e(BASE_URL) ?>/admin/orders/edit?id=<?= e($order['id']) ?>">Ubah Detail</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
</main><?php require dirname(__DIR__) . '/layouts/admin_footer.php'; ?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
